def boss_tactic(phase_count, boss_health):
    # damage calculation
    attack_damage = 10 + (phase_count * 5)
    # health tracking
    if boss_health > 50:
        phase = "normal"
    elif boss_health > 20:
        phase = "aggressive"
    else:
        phase = "final"
    # phase switching logic
    if phase == "final":
        attack_damage *= 2
    return attack_damage, phase
    # This tactic keeps all systems readable in one function

